32	/*
33	    Impedance target test: for each routed track on a copper layer, compute Z₀ from
34	    the active stackup geometry (track width, layer thickness, adjacent dielectric Dk
35	    and height) and verify it falls inside the IMPEDANCE_TARGET_CONSTRAINT's min/max
36	    range.
37	
38	    The model is chosen per track by IMPEDANCE_CALCULATOR::ComputeForTrack(): coupled
39	    microstrip / stripline for differential pairs (checked against the differential target),
40	    (grounded) coplanar where adjacent ground copper is detected, otherwise single-ended
41	    microstrip (outer) / stripline (inner).
42	
43	    Errors generated:
44	    - DRCE_IMPEDANCE_OUT_OF_RANGE
45	*/
46	
47	
48	class DRC_TEST_PROVIDER_IMPEDANCE : public DRC_TEST_PROVIDER
49	{
50	public:
51	    DRC_TEST_PROVIDER_IMPEDANCE() = default;
52	    virtual ~DRC_TEST_PROVIDER_IMPEDANCE() = default;
53	
54	    virtual bool Run() override;
55	
56	    virtual const wxString GetName() const override { return wxT( "impedance" ); }
57	
58	private:
59	    IMPEDANCE_CALCULATOR m_calculator;
60	};
61	
62	
63	bool DRC_TEST_PROVIDER_IMPEDANCE::Run()
64	{
65	    if( m_drcEngine->IsErrorLimitExceeded( DRCE_IMPEDANCE_OUT_OF_RANGE ) )
66	    {
67	        REPORT_AUX( wxT( "Impedance violations ignored. Skipping check." ) );
68	        return true;
69	    }
70	
71	    if( !m_drcEngine->HasRulesForConstraintType( IMPEDANCE_TARGET_CONSTRAINT ) )
72	    {
73	        REPORT_AUX( wxT( "No impedance target constraints found. Tests not run." ) );
74	        return true;
75	    }
76	
77	    if( !reportPhase( _( "Checking track impedance..." ) ) )
78	        return false;
