import { notFound } from "next/navigation";
import { MDXRemote } from "next-mdx-remote/rsc";
import remarkGfm from "remark-gfm";
import rehypeHighlight from "rehype-highlight";
import slugify from "slugify";
import { visit } from "unist-util-visit";
import type { Root, Element } from "hast";

// Custom rehype plugin that adds id attributes to headings using slugify
// (matches the TOC extraction in lib/docs.ts)
function rehypeSlugify() {
  return (tree: Root) => {
    const usedIds = new Set<string>();
    visit(tree, "element", (node: Element) => {
      if (/^h[1-6]$/.test(node.tagName)) {
        const text = getTextContent(node);
        let id = slugify(text, { lower: true, strict: true });
        if (usedIds.has(id)) {
          let counter = 2;
          while (usedIds.has(`${id}-${counter}`)) counter++;
          id = `${id}-${counter}`;
        }
        usedIds.add(id);
        node.properties = node.properties || {};
        node.properties.id = id;
      }
    });
  };
}

function getTextContent(node: Element): string {
  let text = "";
  for (const child of node.children) {
    if (child.type === "text") text += child.value;
    else if (child.type === "element") text += getTextContent(child);
  }
  return text;
}
import Link from "next/link";
import { loadDocPage, loadNavTree, getAllDocSlugs, generateBreadcrumbs } from "@/lib/docs";
import CodeBlock from "./CodeBlock";
import DocImage from "./DocImage";

// Generate static params for all docs
export async function generateStaticParams() {
  const slugs = getAllDocSlugs();
  return slugs.map((slug) => ({ slug }));
}

// Table of contents component
function TableOfContents({ headers }: { headers: { id: string; title: string; depth: number }[] }) {
  const filteredHeaders = headers.filter((h) => h.depth <= 3);

  if (filteredHeaders.length < 2) return null;

  return (
    <nav className="sticky top-[103px] max-h-[calc(100vh-103px)] overflow-y-auto">
      <ul className="space-y-2">
        {filteredHeaders.map((header) => (
          <li
            key={header.id}
            style={{ paddingLeft: `${(header.depth - 1) * 12}px` }}
          >
            <a
              href={`#${header.id}`}
              className="text-sm text-fg4 hover:text-fg transition-colors"
            >
              {header.title}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  );
}

// Breadcrumbs component
function Breadcrumbs({ items }: { items: { text: string; href: string }[] }) {
  return (
    <nav className="flex items-center gap-2 text-sm text-fg4 mb-6">
      {items.map((item, index) => {
        const isLast = index === items.length - 1;
        return (
          <span key={index} className="flex items-center gap-2">
            {index > 0 && <span>/</span>}
            {isLast || !item.href ? (
              <span className={isLast ? "text-fg" : ""}>{item.text}</span>
            ) : (
              <Link href={item.href} className="hover:text-fg transition-colors">
                {item.text}
              </Link>
            )}
          </span>
        );
      })}
    </nav>
  );
}

// MDX components with custom styling
const mdxComponents = {
  h1: ({ children, ...props }: React.HTMLAttributes<HTMLHeadingElement>) => (
    <h1 className="text-3xl font-bold text-fg mb-6 mt-8 first:mt-0 scroll-mt-24" {...props}>
      {children}
    </h1>
  ),
  h2: ({ children, ...props }: React.HTMLAttributes<HTMLHeadingElement>) => (
    <h2 className="text-2xl font-bold text-fg mb-4 mt-8 scroll-mt-24" {...props}>
      {children}
    </h2>
  ),
  h3: ({ children, ...props }: React.HTMLAttributes<HTMLHeadingElement>) => (
    <h3 className="text-xl font-bold text-fg mb-3 mt-6 scroll-mt-24" {...props}>
      {children}
    </h3>
  ),
  h4: ({ children, ...props }: React.HTMLAttributes<HTMLHeadingElement>) => (
    <h4 className="text-lg font-bold text-fg mb-2 mt-4 scroll-mt-24" {...props}>
      {children}
    </h4>
  ),
  p: ({ children, ...props }: React.HTMLAttributes<HTMLParagraphElement>) => (
    <p className="text-fg2 mb-4 leading-relaxed" {...props}>
      {children}
    </p>
  ),
  ul: ({ children, ...props }: React.HTMLAttributes<HTMLUListElement>) => (
    <ul className="list-disc pl-6 text-fg2 mb-4 space-y-1" {...props}>
      {children}
    </ul>
  ),
  ol: ({ children, ...props }: React.HTMLAttributes<HTMLOListElement>) => (
    <ol className="list-decimal pl-6 text-fg2 mb-4 space-y-1" {...props}>
      {children}
    </ol>
  ),
  li: ({ children, ...props }: React.HTMLAttributes<HTMLLIElement>) => (
    <li className="text-fg2" {...props}>
      {children}
    </li>
  ),
  a: ({ href, children, ...props }: React.AnchorHTMLAttributes<HTMLAnchorElement>) => (
    <a
      href={href}
      className="text-[#458588] hover:underline"
      {...props}
    >
      {children}
    </a>
  ),
  code: ({ children, className, ...props }: React.HTMLAttributes<HTMLElement>) => {
    // Inline code
    if (!className) {
      return (
        <code className="bg-bg1 px-1.5 py-0.5 rounded text-sm font-mono text-fg" {...props}>
          {children}
        </code>
      );
    }
    // Code block (handled by pre)
    return (
      <code className={`${className} font-mono`} {...props}>
        {children}
      </code>
    );
  },
  pre: ({ children }: React.HTMLAttributes<HTMLPreElement>) => (
    <CodeBlock>{children}</CodeBlock>
  ),
  img: ({ src, alt }: React.ImgHTMLAttributes<HTMLImageElement>) => (
    <DocImage src={typeof src === "string" ? src : undefined} alt={alt} />
  ),
  blockquote: ({ children, ...props }: React.HTMLAttributes<HTMLQuoteElement>) => (
    <blockquote className="border-l-4 border-bg2 pl-4 italic text-fg4 mb-4" {...props}>
      {children}
    </blockquote>
  ),
  table: ({ children, ...props }: React.HTMLAttributes<HTMLTableElement>) => (
    <div className="overflow-x-auto mb-4">
      <table className="w-full text-sm text-left border-collapse" {...props}>
        {children}
      </table>
    </div>
  ),
  thead: ({ children, ...props }: React.HTMLAttributes<HTMLTableSectionElement>) => (
    <thead className="border-b border-bg2" {...props}>
      {children}
    </thead>
  ),
  th: ({ children, ...props }: React.ThHTMLAttributes<HTMLTableCellElement>) => (
    <th className="px-4 py-2 text-fg font-medium" {...props}>
      {children}
    </th>
  ),
  td: ({ children, ...props }: React.TdHTMLAttributes<HTMLTableCellElement>) => (
    <td className="px-4 py-2 text-fg2 border-t border-bg2" {...props}>
      {children}
    </td>
  ),
  hr: () => <hr className="border-bg2 my-8" />,
  strong: ({ children, ...props }: React.HTMLAttributes<HTMLElement>) => (
    <strong className="font-bold text-fg" {...props}>
      {children}
    </strong>
  ),
};

export default async function DocsPage({
  params,
}: {
  params: Promise<{ slug: string[] }>;
}) {
  const { slug } = await params;

  const page = loadDocPage(slug);
  if (!page) {
    notFound();
  }

  const navItems = loadNavTree();
  const breadcrumbs = generateBreadcrumbs(slug, navItems);

  return (
    <div className="flex justify-center">
      <div className="flex w-full max-w-5xl min-w-0">
        <main className="flex-1 min-w-0 px-8 py-8">
          <Breadcrumbs items={breadcrumbs} />

          <article className="prose prose-invert max-w-none font-sans">
            <MDXRemote
              source={page.content}
              components={mdxComponents}
              options={{
                mdxOptions: {
                  remarkPlugins: [remarkGfm],
                  rehypePlugins: [rehypeSlugify, rehypeHighlight],
                },
              }}
            />
          </article>
        </main>

        <aside className="w-56 shrink-0 px-6 py-8 hidden xl:block">
          <TableOfContents headers={page.headers} />
        </aside>
      </div>
    </div>
  );
}

