import fs from "fs";
import path from "path";
import matter from "gray-matter";
import slugify from "slugify";

const DOCS_PATH = path.join(process.cwd(), "docs");

export interface NavItem {
  type: "link" | "folder" | "break";
  title?: string;
  href?: string;
  children?: NavItem[];
}

export interface DocPage {
  title: string;
  description?: string;
  content: string;
  headers: { id: string; title: string; depth: number }[];
}

export interface NavTreeData {
  items: NavItem[];
  activePath: string;
}

// Load navigation structure
export function loadNavTree(): NavItem[] {
  const navPath = path.join(DOCS_PATH, "nav.json");
  if (!fs.existsSync(navPath)) {
    return [];
  }
  const navContent = fs.readFileSync(navPath, "utf-8");
  return JSON.parse(navContent);
}

// Get all doc slugs for static generation
export function getAllDocSlugs(): string[][] {
  const slugs: string[][] = [];

  function walkNav(items: NavItem[]) {
    for (const item of items) {
      if (item.type === "link" && item.href) {
        // Remove leading /docs/ and split into segments
        const slug = item.href.replace(/^\/docs\/?/, "").split("/").filter(Boolean);
        if (slug.length > 0) {
          slugs.push(slug);
        }
      }
      if (item.type === "folder" && item.children) {
        walkNav(item.children);
      }
    }
  }

  walkNav(loadNavTree());
  return slugs;
}

// Extract headers from markdown content
function extractHeaders(content: string): { id: string; title: string; depth: number }[] {
  const headers: { id: string; title: string; depth: number }[] = [];
  const headerRegex = /^(#{1,6})\s+(.+)$/gm;
  const usedIds = new Set<string>();

  let match;
  while ((match = headerRegex.exec(content)) !== null) {
    const depth = match[1].length;
    const title = match[2].trim();
    let id = slugify(title, { lower: true, strict: true });

    // Handle duplicate IDs
    if (usedIds.has(id)) {
      let counter = 2;
      while (usedIds.has(`${id}-${counter}`)) {
        counter++;
      }
      id = `${id}-${counter}`;
    }
    usedIds.add(id);

    headers.push({ id, title, depth });
  }

  return headers;
}

// Load a single doc page
export function loadDocPage(slugArray: string[]): DocPage | null {
  const slugPath = slugArray.join("/");

  // Try direct file first, then index file
  const possiblePaths = [
    path.join(DOCS_PATH, `${slugPath}.mdx`),
    path.join(DOCS_PATH, `${slugPath}.md`),
    path.join(DOCS_PATH, slugPath, "index.mdx"),
    path.join(DOCS_PATH, slugPath, "index.md"),
  ];

  let filePath: string | null = null;
  for (const p of possiblePaths) {
    if (fs.existsSync(p)) {
      filePath = p;
      break;
    }
  }

  if (!filePath) {
    return null;
  }

  const fileContent = fs.readFileSync(filePath, "utf-8");
  const { data: frontmatter, content } = matter(fileContent);

  const headers = extractHeaders(content);

  return {
    title: frontmatter.title || slugArray[slugArray.length - 1] || "Documentation",
    description: frontmatter.description,
    content,
    headers,
  };
}

// Generate breadcrumbs from slug and nav tree
export function generateBreadcrumbs(
  slugArray: string[],
  navItems: NavItem[]
): { text: string; href: string }[] {
  const breadcrumbs: { text: string; href: string }[] = [
    { text: "Docs", href: "/docs" },
  ];

  const targetPath = `/docs/${slugArray.join("/")}`;

  // Find the chain of nav items (folders + final link) leading to targetPath
  function findChain(items: NavItem[]): NavItem[] | null {
    for (const item of items) {
      if (item.type === "link" && item.href === targetPath) {
        return [item];
      }
      if (item.type === "folder" && item.children) {
        const childChain = findChain(item.children);
        if (childChain) return [item, ...childChain];
      }
    }
    return null;
  }

  const chain = findChain(navItems);
  if (chain) {
    for (const item of chain) {
      if (item.title) {
        breadcrumbs.push({ text: item.title, href: item.href ?? "" });
      }
    }
  }

  return breadcrumbs;
}

