/*
 * Signal-Integrity Analysis Parameters
 * Board-wide analysis inputs for the impedance / transmission-line calculation
 * (Board Setup -> Board Stackup -> Impedance). These are analysis inputs, not
 * physical stackup geometry — per-dielectric Dk/Df and per-layer thickness live
 * in BOARD_STACKUP. Fields are optional so a set can update a subset.
 */
message SignalIntegrityParams
{
  optional double reference_frequency_hz = 1;       // Frequency impedance/loss is evaluated at (default 1e9)
  optional double dk_measurement_frequency_hz = 2;  // Frequency the stackup Dk/Df were specified at (default 1e9)
  optional double conductor_resistivity_ohm_m = 3;  // Conductor resistivity, ohm-metres (default 1.72e-8, copper @ 20C)
  optional double conductor_roughness_m = 4;        // RMS copper surface roughness, metres (default 0)
}

// Get signal-integrity analysis parameters
// Returns SignalIntegrityParamsResponse
message GetSignalIntegrityParams
{
  kiapi.common.types.DocumentSpecifier board = 1;
}

message SignalIntegrityParamsResponse
{
  SignalIntegrityParams params = 1;
}

// Set signal-integrity analysis parameters (only provided fields are updated)
// Returns SignalIntegrityParamsResponse with the full updated set
message SetSignalIntegrityParams
{
  kiapi.common.types.DocumentSpecifier board = 1;
  SignalIntegrityParams params = 2;
}

