message SetSignalIntegrityParams
{
  kiapi.common.types.DocumentSpecifier board = 1;
  SignalIntegrityParams params = 2;
}


/*
 * Impedance readback (computed, not target)
 * Characteristic/differential impedance and insertion loss for routed copper, from the
 * transmission-line model (IMPEDANCE_CALCULATOR). Requires a stackup with at least one
 * dielectric Dk > 1; otherwise stackup_has_dk is false and results are empty.
 */
enum ImpedanceModel
{
  IM_NONE = 0;
  IM_MICROSTRIP = 1;          // single-ended, outer layer over a plane
  IM_STRIPLINE = 2;           // single-ended, inner layer between planes
  IM_COPLANAR = 3;            // coplanar waveguide (side grounds, no back plane)
  IM_GROUNDED_COPLANAR = 4;   // grounded coplanar waveguide (side grounds + back plane)
  IM_COUPLED_MICROSTRIP = 5;  // differential pair, outer layer
  IM_COUPLED_STRIPLINE = 6;   // differential pair, inner layer
}

// Per-net length-weighted average impedance (mirrors the Net Inspector column).
message NetImpedance
{
  int32 net_code = 1;
  string net_name = 2;
  int32 average_impedance_ohms = 3;  // model-aware: Z_diff for diff pairs, CPW Z0 for coplanar, else Z0
  bool is_differential = 4;          // routing was modelled as a differential pair
  double insertion_loss_db = 5;      // total insertion loss over the routed length
  int64 routed_length_nm = 6;        // total routed copper length used for the average
}

// Get per-net average impedance for routed nets.
// Returns NetImpedanceResponse. Nets with no usable impedance are omitted.
message GetNetImpedance
{
  kiapi.common.types.DocumentSpecifier board = 1;
  optional string net_name = 2;  // restrict to one net; empty = all routed nets
}

message NetImpedanceResponse
{
  repeated NetImpedance nets = 1;
  bool stackup_has_dk = 2;  // false => stackup defines no dielectric constants; results empty
}

// Per-track impedance for the segments of a single net.
message TrackImpedance
{
  kiapi.common.types.KIID track_id = 1;
  kiapi.board.types.BoardLayer layer = 2;
  int64 width_nm = 3;
  int64 length_nm = 4;
  int32 single_ended_ohms = 5;
  int32 differential_ohms = 6;  // 0 unless a coupled model was used
  ImpedanceModel model = 7;
  double insertion_loss_db_per_inch = 8;
}

// Get per-track impedance for one net (net_name required, to bound output size).
// Returns TrackImpedanceResponse.
message GetTrackImpedance
{
  kiapi.common.types.DocumentSpecifier board = 1;
  string net_name = 2;  // required: net whose track segments to report
}

message TrackImpedanceResponse
{
  repeated TrackImpedance tracks = 1;
  bool stackup_has_dk = 2;
}

